<script lang="ts">import type {Snippet} from "svelte";import {createTooltipController} from "@civaria/core";import {normalizeSvelteProps} from "./internal.js";let {content,delay=0,id="civ-tooltip",children}=$props<{content:string;delay?:number;id?:string;children?:Snippet}>();const controller=createTooltipController({id,delay});let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});function p(kind:"root"|"trigger"|"content"){state;return normalizeSvelteProps(kind==="root"?controller.getRootProps():kind==="trigger"?controller.getTriggerProps():controller.getContentProps())}</script><span {...p("root")} class="civ-tooltip"><span {...p("trigger")} class="civ-tooltip__trigger" tabindex="0">{@render children?.()}</span><span {...p("content")} class="civ-tooltip__content">{content}</span></span>
